parameters.jsCode:
const duration = $json.duration;
const sceneCount = $json.sceneCount;

const checks = {
  durationValid: duration > 0 && duration <= 180,
  scenesValid: sceneCount > 0,
  inputValid: Boolean($json.topic && $json.audience)
};

const qualityPass = Object.values(checks).every(Boolean);

return {
  ...$json,
  qualityChecks: checks,
  qualityPass
};

return {
  ...$json,

  seo: {
    title: "",
    description: "",
    keywords: [],
    tags: [],
    caption: "",
    hashtags: []
  }
};

parameters.jsonBody:
={
  "model": "gemma3:1b",
  "prompt": "Write a 60-second spoken narration about Artificial Intelligence in Education for college students. Create exactly 6 scenes. Stay strictly on AI in Education. Do not discuss social media automation, marketing, customers, or content calendars. Scene 1: Introduction. Scene 2: How AI helps students. Scene 3: Personalized learning. Scene 4: AI tools and practical applications. Scene 5: Benefits and limitations. Scene 6: Future and conclusion. Each scene should have about 18 to 22 spoken words. Return ONLY valid JSON with exactly this structure: {\"script\":[{\"scene\":1,\"narration\":\"...\"},{\"scene\":2,\"narration\":\"...\"},{\"scene\":3,\"narration\":\"...\"},{\"scene\":4,\"narration\":\"...\"},{\"scene\":5,\"narration\":\"...\"},{\"scene\":6,\"narration\":\"...\"}]}",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
const raw = $json.response;

if (!raw) {
  throw new Error("Script Agent returned no response");
}

let data;
let text = String(raw)
  .replace(/```json/gi, "")
  .replace(/```/g, "")
  .trim();

// Try to parse the AI response
try {
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");

  if (start !== -1 && end !== -1) {
    data = JSON.parse(text.substring(start, end + 1));
  } else {
    data = JSON.parse(text);
  }
} catch (error) {
  data = null;
}

// Collect any scenes the AI actually returned
let aiScenes = [];

if (data && Array.isArray(data.script)) {
  aiScenes = data.script;
} else if (Array.isArray(data)) {
  aiScenes = data;
} else if (data && data.scene && data.narration) {
  aiScenes = [data];
}

// Keep valid narration only
const narrations = aiScenes
  .filter(scene => scene && scene.narration)
  .map(scene => String(scene.narration).trim());

// If AI returned fewer than 6 usable scenes,
// create a reliable 6-scene educational script.
const fallback = [
  "Artificial intelligence is changing the way students learn and teachers teach.",
  "AI tools can help students understand difficult topics and find useful learning resources.",
  "Personalized learning systems can adapt lessons and practice to a student's needs.",
  "Teachers can use AI to save time and provide students with faster feedback.",
  "However, students should use AI responsibly and always verify the information it provides.",
  "The future of education will combine human teaching with AI to create better learning experiences."
];

// Use AI scenes when available, then fill missing scenes.
const finalScenes = [];

for (let i = 0; i < 6; i++) {
  finalScenes.push({
    scene: i + 1,
    narration: narrations[i] || fallback[i]
  });
}

return {
  script: finalScenes
};

parameters.jsonBody:
={
  "model": "gemma3:1b",
  "prompt": "You are the Scene Agent for a college project. Convert the following 6-scene script into simple visual descriptions for a vertical 9:16 educational video. Create exactly 6 scenes numbered 1 to 6. Do not create scene 7. Each scene must contain scene, visual, and duration. Keep visuals simple. Do not use copyrighted characters, logos, or footage. Return ONLY valid JSON in this exact structure: {\"scenes\":[{\"scene\":1,\"visual\":\"...\",\"duration\":10},{\"scene\":2,\"visual\":\"...\",\"duration\":10},{\"scene\":3,\"visual\":\"...\",\"duration\":10},{\"scene\":4,\"visual\":\"...\",\"duration\":10},{\"scene\":5,\"visual\":\"...\",\"duration\":10},{\"scene\":6,\"visual\":\"...\",\"duration\":10}]}. SCRIPT: {{ JSON.stringify($json.scenes).replace(/\\\\/g, '\\\\\\\\').replace(/\"/g, '\\\\\"') }}",
  "stream": false,
  "format": "json"
}

parameters.jsCode:
const response = $json.response;

if (!response) {
  throw new Error("Scene Agent returned no response");
}

let data;

try {
  data = typeof response === "string"
    ? JSON.parse(response)
    : response;
} catch (error) {
  throw new Error("Invalid JSON from Scene Agent: " + error.message);
}

// If the AI returned { scenes: [...] }
if (data.scenes && Array.isArray(data.scenes)) {
  return {
    scenes: data.scenes
  };
}

// If the AI returned an array directly
if (Array.isArray(data)) {
  return {
    scenes: data
  };
}

// If n8n received one scene object
if (data.scene && data.visual) {
  return {
    scenes: [data]
  };
}

throw new Error(
  "Could not find scene data. Response was: " +
  JSON.stringify(data)
);

